INSERT INTO jobs (job_id, company_id, title, city, category, salary_min_minor, salary_max_minor, salary_months, experience, education, jd, requirements, tags, status, posted_at) VALUES
  ('jb-4vxnibjsgwrdx', 'comp_meituan', 'Senior Backend Engineer（Java）', 'Shanghai', 'backend', 3000000, 4000000, 16, '5-10', 'master', 'Own the Meituan order transaction platform end to end: sharding, idempotency compensation, capacity governance, end-to-end load testing, distributed transactions, and hot traffic incident review at e-commerce peak scale.', 'Solid Java and Spring Cloud foundation; hands-on sharding, distributed transactions, idempotency compensation, and capacity governance; drives end-to-end load testing and incident review.', 'Java,Spring Cloud,backend', 'open', '2026-05-02T09:00:00Z'),
  ('jb-n3e27mxldw6bx', 'comp_xiaohongshu', 'Backend Engineer（Go）', 'Shanghai', 'backend', 4000000, 6500000, 16, '3-5', 'bachelor', 'Build Xiaohongshu feed and note services: orders, inventory, cache consistency, message queues, observability, and hot products reliability during e-commerce peak traffic.', 'Strong Go or Java background; cache consistency, message queues, observability; hot products and e-commerce peak reliability.', 'Go,backend,Java', 'open', '2026-05-03T09:00:00Z'),
  ('jb-a3ltos7t5ortx', 'comp_zhipu', 'Backend Engineer（Go/AI Platform）', 'Shanghai', 'backend', 5000000, 8000000, 15, '5-10', 'master', 'Build the Zhipu AI training and inference platform: GPU scheduling, Kubernetes, inference framework gateways, and stable distributed systems services.', 'Experience with Go/C++, Kubernetes, GPU scheduling, inference frameworks, and API gateways for distributed systems.', 'Go,backend,Kubernetes', 'open', '2026-05-04T09:00:00Z'),
  ('jb-tb2gjepdyi66x', 'comp_bilibili', 'English text（English text）', 'Shanghai', 'backend', 3800000, 6000000, 15, '3-5', 'bachelor', 'English text、English text，English text。', 'English text，English text Go/Java、Netty、English text、English text。', 'Go,English text,English text', 'open', '2026-05-05T09:00:00Z'),
  ('jb-2jzt2pu3dgjvx', 'comp_borchina', 'English text（English text）', 'Shanghai', 'backend', 5500000, 8500000, 14, '5-10', 'master', 'This role sits on client projects under an IT outsourcing arrangement: labor dispatch staffing, long-term on-site work at the customer data center, and headcount billing by person-month.', 'Outsourcing delivery profile; dispatched to client sites for on-site development and O&M under a labor dispatch contract.', 'Java,English text,English text', 'open', '2026-05-06T09:00:00Z'),
  ('jb-2dwm2nq5ea3mx', 'comp_ruijietech', 'English text（English text）', 'Shanghai', 'backend', 5200000, 8000000, 14, '3-5', 'bachelor', 'Outsourcing delivery role: dispatched to a banking client site for long-term on-site development and O&M; the labor dispatch contract is with the vendor, not the end client.', 'Dispatch staffing model with on-site client work under an IT outsourcing agreement.', 'Java,English text,English text', 'open', '2026-05-07T09:00:00Z'),
  ('jb-ippyupc52h4qx', 'comp_dewu', 'English text（English text）', 'Shanghai', 'backend', 4800000, 7200000, 16, '5-10', 'master', 'Own Poizon trading platform Java services. Offer note: a two-year noncompete without compensation applies after departure; noncompete compensation is not specified in the draft contract.', 'Strong Java background; trading platform experience preferred; review the noncompete restriction before accepting.', 'Java,English text,English text', 'open', '2026-05-08T09:00:00Z'),
